CREATE TABLE IF NOT EXISTS "ClubRegistrationRequest" ("id" SERIAL PRIMARY KEY, "userId" INTEGER NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "city" TEXT NOT NULL, "shortName" TEXT NOT NULL DEFAULT '', "status" TEXT NOT NULL DEFAULT 'PENDING', "reason" TEXT NOT NULL DEFAULT '', "clubId" INTEGER, "reviewedBy" INTEGER, "reviewedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "mailStatus" TEXT NOT NULL DEFAULT 'NONE', "mailAttempts" INTEGER NOT NULL DEFAULT 0, "mailNextAt" TIMESTAMP(3), "mailSentAt" TIMESTAMP(3));
CREATE INDEX IF NOT EXISTS "ClubRegistrationRequest_status_createdAt_idx" ON "ClubRegistrationRequest"("status", "createdAt");
CREATE INDEX IF NOT EXISTS "ClubRegistrationRequest_mailStatus_mailNextAt_idx" ON "ClubRegistrationRequest"("mailStatus", "mailNextAt");
CREATE TABLE IF NOT EXISTS "ClubNamePolicy" ("id" INTEGER PRIMARY KEY DEFAULT 1, "revision" INTEGER NOT NULL DEFAULT 0, "terms" JSONB NOT NULL DEFAULT '[]', "rules" TEXT NOT NULL DEFAULT 'Utilisez le nom réel de votre club d’escrime et sa ville. Les noms injurieux, discriminatoires, menaçants, à caractère sexuel, publicitaires ou usurpant une identité sont refusés. Chaque ajout doit être validé par un administrateur. En attendant, vous restez sans club / accompagnant. Vous pouvez demander un réexamen auprès de l’éditeur.', "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
